INSERT INTO factors
  (id, spatial_path, name, description, effect, significance, lat, lon, verification_state, created_at, updated_at)
VALUES
  ('f0000000-0000-4000-8000-000000000001', 'global'::ltree, 'Arctic sea ice — record-low winter maximum', 'The 2025 Arctic sea-ice winter maximum was the lowest in the 47-year satellite record at 14.33 million km², about 1.31 million km² below the 1981–2010 average. Loss of reflective ice weakens the planetary albedo shield, a self-reinforcing warming feedback.', -0.85, 0.9, 85, 0, 'verified', '2026-06-01T12:00:00.000Z'::timestamptz, '2026-06-01T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000002', 'global'::ltree, 'Permafrost carbon feedback', 'Northern permafrost soils hold roughly 1,460–1,600 gigatons of organic carbon, about twice the amount currently in the atmosphere. Thaw converts this store into CO₂ and methane in an accelerating feedback that is poorly represented in most climate models.', -0.9, 0.85, 67.5, 100, 'verified', '2026-06-02T12:00:00.000Z'::timestamptz, '2026-06-02T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000003', 'global.br'::ltree, 'Amazon forest — critical transition risk', 'By 2050 an estimated 10–47% of the Amazon could face compounding stressors (warming, drought, fire, deforestation) capable of triggering large-scale dieback from rainforest to savanna. The southeastern Amazon is already a net carbon source.', -0.8, 0.85, -3.47, -62.2, 'verified', '2026-06-03T12:00:00.000Z'::timestamptz, '2026-06-03T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000004', 'global'::ltree, 'AMOC — weakening and possible collapse', 'Freshwater input from Greenland and Arctic melt is weakening the Atlantic Meridional Overturning Circulation. A collapse would disrupt monsoons billions depend on and could cool parts of Europe. Timing is scientifically contested.', -0.78, 0.75, 59, -30, 'verified', '2026-06-04T12:00:00.000Z'::timestamptz, '2026-06-04T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000005', 'global'::ltree, 'Global pollinator decline', 'The 2016 IPBES assessment (>3,000 studies) found over 40% of invertebrate pollinator species — chiefly bees and butterflies — face extinction. Over 75% of food crop types depend on animal pollination, valued at US$235–577 billion annually.', -0.7, 0.8, 20, 0, 'verified', '2026-06-05T12:00:00.000Z'::timestamptz, '2026-06-05T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000006', 'global'::ltree, 'Coral reef collapse at 2°C', 'The IPCC projects coral reefs decline 70–90% at 1.5°C of warming and by more than 99% at 2°C. With 1.5°C breached for a full calendar year in 2024, this is a present-day trajectory rather than a distant projection.', -0.72, 0.75, -18.28, 147.7, 'verified', '2026-06-06T12:00:00.000Z'::timestamptz, '2026-06-06T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000007', 'global'::ltree, '2024 — warmest year on record', '2024 was the warmest year in the 175-year observational record at 1.55°C ± 0.13°C above the 1850–1900 average — the first full calendar year above 1.5°C. The ten warmest years on record are all within the last decade.', -0.9, 0.95, 0, 0, 'verified', '2026-06-07T12:00:00.000Z'::timestamptz, '2026-06-07T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000008', 'global.us'::ltree, 'Regulatory capture via lobbying', 'US federal lobbying reached a record ~$4.4 billion in 2024, with pharmaceuticals, electronics and energy among the heaviest spenders — a direct mechanism by which incumbents blunt regulation of Clock-accelerating industries.', -0.55, 0.6, 38.8977, -77.0365, 'verified', '2026-06-08T12:00:00.000Z'::timestamptz, '2026-06-08T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000009', 'global.us'::ltree, 'Cloud infrastructure concentration', 'As of Q4 2024 three firms — Amazon (AWS, 30%), Microsoft (Azure, 21%) and Google (12%) — controlled a combined 63% of the global cloud infrastructure market, giving a handful of actors structural control over the compute layer of the modern economy.', -0.45, 0.55, 47.6062, -122.3321, 'verified', '2026-06-09T12:00:00.000Z'::timestamptz, '2026-06-09T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000010', 'global'::ltree, 'Wealth concentration', 'Oxfam’s 2025 "Takers Not Makers" report projects the world could mint its first trillionaires within a decade and finds roughly 60% of billionaire wealth is inherited or derived from monopoly power and cronyism — a structural concentration of economic power.', -0.6, 0.7, 46.8, 9.83, 'verified', '2026-06-10T12:00:00.000Z'::timestamptz, '2026-06-10T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000011', 'global'::ltree, 'AI-driven labour displacement', 'Goldman Sachs estimates generative AI could expose the equivalent of 300 million full-time jobs to automation globally, concentrated in office, administrative and legal work — reallocating labour toward a smaller high-skill cohort.', -0.5, 0.6, 37.7749, -122.4194, 'verified', '2026-06-11T12:00:00.000Z'::timestamptz, '2026-06-11T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000012', 'global'::ltree, 'Active conflicts at a post-WWII high', 'The 2024 Global Peace Index records 56 active conflicts — the most since World War II — with 92 countries involved in conflicts beyond their borders. Climate stress acts as a "threat multiplier" over scarce resources.', -0.68, 0.72, 15, 30, 'verified', '2026-06-12T12:00:00.000Z'::timestamptz, '2026-06-12T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000013', 'global'::ltree, 'Textile waste — the fast-fashion linear model', 'The fast-fashion model generates enormous textile waste. US EPA data show 17 million tons of textiles generated in 2018 with only a 14.7% recycling rate — a verifiable snapshot of a globally replicated take-make-discard system.', -0.4, 0.45, 23.8103, 90.4125, 'verified', '2026-06-13T12:00:00.000Z'::timestamptz, '2026-06-13T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000014', 'global.us'::ltree, 'Planned obsolescence', 'The deliberate shortening of product lifespans is a documented corporate strategy. Apple’s "Batterygate" — throttling older iPhones via software — settled US class actions for up to $500 million, echoing the 1920s–30s Phoebus lightbulb cartel’s enforced 1,000-hour bulb standard.', -0.35, 0.45, 37.3349, -122.009, 'verified', '2026-06-14T12:00:00.000Z'::timestamptz, '2026-06-14T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000016', 'global'::ltree, 'Synchronised breadbasket failure risk', 'Destabilised jet-stream patterns raise the risk of simultaneous crop failures across major exporters. A PNAS study finds the probability that the top four maize exporters (US, Brazil, Argentina, Ukraine) all lose >10% in one year rises from ~0% today to 86% under 4°C warming.', -0.6, 0.6, 41.5, -93.6, 'pending', '2026-06-16T12:00:00.000Z'::timestamptz, '2026-06-16T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000017', 'global'::ltree, 'AI-amplified misinformation', 'The World Economic Forum’s 2024 Global Risks Report ranks misinformation and disinformation — supercharged by generative AI — as the most severe short-term (two-year) global risk, ahead of extreme weather and armed conflict, by eroding the shared reality required for collective action.', -0.55, 0.6, 20, 0, 'verified', '2026-06-17T12:00:00.000Z'::timestamptz, '2026-06-17T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000018', 'global'::ltree, 'Clean energy investment overtakes fossil fuels', 'The IEA projects ~$2.2 trillion of clean-energy investment in 2025 — roughly double the $1.1 trillion going to oil, gas and coal. A decade ago fossil-supply investment led electricity investment by 30%; today the positions are reversed.', 0.72, 0.75, 0, 0, 'verified', '2026-06-18T12:00:00.000Z'::timestamptz, '2026-06-18T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000019', 'global'::ltree, 'Solar and wind are the cheapest new power', 'IRENA finds new onshore wind (~US$0.034/kWh) and utility-scale solar PV (~US$0.043/kWh) are now the cheapest sources of new electricity in most of the world; 81% of renewable capacity added in 2023 produced cheaper power than the cheapest fossil alternative.', 0.68, 0.7, 10, 0, 'pending', '2026-06-19T12:00:00.000Z'::timestamptz, '2026-06-19T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000020', 'global'::ltree, 'Renewable energy — a positive tipping point', 'The 2023 Global Tipping Points Report (200+ researchers, University of Exeter) finds positive tipping points already crossed in solar and wind adoption: solar PV capacity is doubling every 2–3 years as cost-reduction and deployment reinforce each other.', 0.6, 0.62, 5, 0, 'pending', '2026-06-20T12:00:00.000Z'::timestamptz, '2026-06-20T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000021', 'global.de'::ltree, 'Community energy cooperatives', 'Citizen-owned renewable projects are scaling a decentralised alternative to fossil incumbency. REScoop.eu represents over 2,250 European energy cooperatives and ~1.5 million citizens; Germany alone hosts more than 1,000 cooperatives.', 0.42, 0.45, 51.1657, 10.4515, 'pending', '2026-06-21T12:00:00.000Z'::timestamptz, '2026-06-21T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000022', 'global'::ltree, 'Open-source environmental monitoring', 'Global Forest Watch (World Resources Institute, with NASA/ESA/UMD data) delivers free, open, near-real-time forest-change alerts to anyone — a transparency counter-force to the information asymmetry that hides degradation. Weekly GLAD alerts at 30m; RADD alerts at 10m in the tropics.', 0.4, 0.4, 38.8895, -77.0353, 'pending', '2026-06-22T12:00:00.000Z'::timestamptz, '2026-06-22T12:00:00.000Z'::timestamptz),
  ('f0000000-0000-4000-8000-000000000023', 'global.us'::ltree, 'Decentralised coordination — the GameStop episode', 'In January 2021 retail investors coordinating openly on Reddit’s r/wallstreetbets drove a short squeeze that lifted GameStop from a $17.25 close to over $500 intraday, inflicting billions in losses on short-selling hedge funds — a demonstration that distributed actors can rapidly out-coordinate concentrated capital.', 0.35, 0.4, 40.706, -74.009, 'verified', '2026-06-23T12:00:00.000Z'::timestamptz, '2026-06-23T12:00:00.000Z'::timestamptz)
INSERT INTO citations
  (id, factor_id, source_url, publisher, quote_snippet, analyst_notes, retrieved_at)
VALUES
  ('c0000000-0000-4000-8000-000000000001', 'f0000000-0000-4000-8000-000000000001', 'https://nsidc.org/sea-ice-today/analyses/arctic-sea-ice-sets-record-low-maximum-2025', 'National Snow and Ice Data Center (NSIDC)', 'On March 22, Arctic sea ice likely reached its maximum extent for the year, at 14.33 million square kilometers, the lowest in the 47-year satellite record.', NULL, '2026-06-01T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000002', 'f0000000-0000-4000-8000-000000000002', 'https://www.nature.com/articles/nature14338', 'Nature (Schuur et al., 2015, "Climate change and the permafrost carbon feedback")', 'Northern permafrost soils hold on the order of 1,460–1,600 gigatons of organic carbon — roughly twice the carbon currently in the atmosphere.', 'Re-pointed to Schuur et al. (2015), the source-review entry for the permafrost carbon stock; NOAA Arctic Report Card figures corroborate the ~1,460–1,600 GtC range (the essay’s 1,400–1,700 Gt band additionally includes deep deposits). Abrupt-thaw acceleration and its poor representation in most Earth-system models are documented separately (Turetsky et al., 2020).', '2026-06-02T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000003', 'f0000000-0000-4000-8000-000000000003', 'https://www.nature.com/articles/s41586-023-06970-0', 'Nature (Flores et al., 2024, "Critical transitions in the Amazon forest system")', 'By 2050, 10% to 47% of Amazonian forests will be exposed to compounding disturbances that may trigger unexpected ecosystem transitions.', 'The often-quoted 20–25% deforestation tipping threshold (vs. ~17% cleared today) is from Lovejoy & Nobre (2018, Science Advances); it is carried in the description but attributed separately as it is a distinct estimate.', '2026-06-03T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000004', 'f0000000-0000-4000-8000-000000000004', 'https://www.nature.com/articles/s41467-023-39810-w', 'Nature Communications (Ditlevsen & Ditlevsen, 2023)', 'The Atlantic Meridional Overturning Circulation is warned to be on course to collapse around mid-century, with a 95% confidence range of 2025–2095.', 'Correction (source review): the essay’s “95% CI at 2065, bounds 2037–2109” does NOT match the paper. Ditlevsen & Ditlevsen give a 95% confidence range of 2025–2095, central estimate around mid-century. The result remains contested across the field, so significance is held below the harder-observed climate factors.', '2026-06-04T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000005', 'f0000000-0000-4000-8000-000000000005', 'https://www.ipbes.net/assessment-reports/pollinators', 'IPBES (Assessment Report on Pollinators, Pollination and Food Production, 2016)', 'Over 40% of invertebrate pollinator species — particularly bees and butterflies — face extinction; US$235–577 billion of annual global food production relies on pollinators.', 'Correction (source review): pollination services are valued as a $235–577 billion/yr RANGE; the essay’s “up to $577B” top-of-range figure is carried as the full range, not just the maximum.', '2026-06-05T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000006', 'f0000000-0000-4000-8000-000000000006', 'https://www.ipcc.ch/sr15/', 'IPCC Special Report on Global Warming of 1.5°C (2018)', 'Coral reefs are projected to decline by a further 70–90% at 1.5°C (high confidence) with larger losses (>99%) at 2°C (very high confidence).', 'Pin placed at the Great Barrier Reef as a representative point; the phenomenon is global (all tropical reef systems).', '2026-06-06T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000007', 'f0000000-0000-4000-8000-000000000007', 'https://wmo.int/news/media-centre/wmo-confirms-2024-warmest-year-record-about-155degc-above-pre-industrial-level', 'World Meteorological Organization (WMO)', 'The global average surface temperature in 2024 was 1.55 °C (± 0.13 °C) above the 1850–1900 average, making it the warmest year in the 175-year observational record.', 'A single year above 1.5°C does not by itself breach the Paris long-term goal, which is defined over decades; this is noted to avoid overstating the claim.', '2026-06-07T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000008', 'f0000000-0000-4000-8000-000000000008', 'https://www.opensecrets.org/news/2025/02/federal-lobbying-set-new-record-in-2024/', 'OpenSecrets', 'In 2024, lobbying spending reached a record-breaking $4.4 billion.', 'Correction (source review): the essay states $4.5 billion (a Bloomberg Government tally). OpenSecrets, the standard registry-based source, reports $4.4 billion for 2024; the corrected $4.4B figure is used.', '2026-06-08T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000009', 'f0000000-0000-4000-8000-000000000009', 'https://www.srgresearch.com/articles/cloud-market-jumped-to-330-billion-in-2024-genai-is-now-driving-half-of-the-growth', 'Synergy Research Group', 'The Big Three — AWS at 30%, Microsoft at 21% and Google at 12% — together hold 63% of the worldwide cloud infrastructure market.', 'Placed at Seattle (AWS/Azure region hub) as a representative US point; the market is global but the controlling firms are US-domiciled.', '2026-06-09T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000010', 'f0000000-0000-4000-8000-000000000010', 'https://policy-practice.oxfam.org/resources/takers-not-makers-621668/', 'Oxfam ("Takers Not Makers", 2025)', 'Oxfam projects the world’s first trillionaires within a decade, and finds around 60% of billionaire wealth comes from inheritance, monopoly power or cronyism.', 'Source re-pointed from a secondary news aggregator to Oxfam’s own "Takers Not Makers" (2025), the bibliography entry. The separate "top 1% own 43% of global financial assets" figure belongs to Oxfam’s Sept-2024 report and is not carried here, to keep one claim per source. Pin placed near Davos as a representative point; the phenomenon is global.', '2026-06-10T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000011', 'f0000000-0000-4000-8000-000000000011', 'https://www.goldmansachs.com/insights/articles/generative-ai-could-raise-global-gdp-by-7-percent', 'Goldman Sachs Global Investment Research (2023)', 'Generative AI could expose the equivalent of 300 million full-time jobs to automation worldwide.', 'Counter-evidence carried deliberately: firm-level studies (PwC, Brookings) find AI adoption correlates with higher employment and wage premiums for AI-skilled workers — the effect is reallocation, not simple destruction. Correction (source review): the essay’s "77% of new AI jobs require a master’s" is an overstatement; Lightcast data indicate roughly two-thirds of AI-engineering postings require a master’s or higher (~43% master’s + ~23% PhD/professional), and PwC’s 2025 Barometer finds degree requirements for AI-exposed jobs falling.', '2026-06-11T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000012', 'f0000000-0000-4000-8000-000000000012', 'https://www.economicsandpeace.org/wp-content/uploads/2024/06/GPI-2024-web.pdf', 'Institute for Economics & Peace — Global Peace Index 2024', 'There are currently 56 conflicts, the most since World War II, and 92 countries are involved in conflicts outside their borders — the most since the GPI’s inception.', NULL, '2026-06-12T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000013', 'f0000000-0000-4000-8000-000000000013', 'https://www.epa.gov/facts-and-figures-about-materials-waste-and-recycling/textiles-material-specific-data', 'US Environmental Protection Agency', 'EPA estimated that the generation of textiles in 2018 was 17 million tons, and the recycling rate for all textiles was 14.7 percent.', 'The essay’s "92 million tonnes/year" global figure is an industry estimate (aggregating UNEP / Ellen MacArthur); the EPA numbers are used as the directly verifiable US subset. Pin placed at Dhaka as a representative garment-production hub.', '2026-06-13T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000014', 'f0000000-0000-4000-8000-000000000014', 'https://www.npr.org/2020/11/18/936268845/apple-agrees-to-pay-113-million-to-settle-batterygate-case-over-iphone-slowdowns', 'NPR', 'Apple agreed to pay $113 million to 34 states to settle claims over the "batterygate" slowdown of older iPhones — on top of a separate class-action settlement of up to $500 million.', 'The bibliography source (NPR) covers both the $113M 34-state AG settlement and the separate $500M class-action settlement; the description’s $500M refers to the latter.', '2026-06-14T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000015', 'f0000000-0000-4000-8000-000000000014', 'https://spectrum.ieee.org/the-great-lightbulb-conspiracy', 'IEEE Spectrum (Krajewski, "The Great Lightbulb Conspiracy", 2014)', 'The Phoebus cartel standardised incandescent bulb life down to about 1,000 hours (from ~2,500), fining members whose bulbs lasted longer.', 'Re-pointed to the IEEE Spectrum history of the Phoebus cartel (the bibliography entry); the prior null sourceUrl is replaced with the canonical article.', '2026-06-14T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000016', 'f0000000-0000-4000-8000-000000000016', 'https://www.pnas.org/doi/abs/10.1073/pnas.1718031115', 'PNAS (Tigchelaar et al., 2018)', 'The probability of simultaneous maize production losses greater than 10% across the top exporters increases to 7% under 2 °C warming and 86% under 4 °C warming.', 'Not in the source review: Tigchelaar et al. (2018, PNAS) is a real primary source but was not part of the source review, so this factor is held at "pending" and kept off the verified field and the Clock aggregate until it is reviewed. Pin placed in the US Corn Belt as a representative production region; the risk is joint across all four exporters.', '2026-06-16T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000017', 'f0000000-0000-4000-8000-000000000017', 'https://www.weforum.org/publications/global-risks-report-2024/', 'World Economic Forum — Global Risks Report 2024', 'Misinformation and disinformation is ranked the most severe short-term (two-year) global risk.', NULL, '2026-06-17T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000018', 'f0000000-0000-4000-8000-000000000018', 'https://www.iea.org/reports/world-energy-investment-2025', 'International Energy Agency — World Energy Investment 2025', 'Around USD 2.2 trillion is going collectively to clean energy in 2025, twice as much as the USD 1.1 trillion going to oil, natural gas and coal.', 'Solar (~$450B) is the single largest line item in the report; clean-energy investment now leads fossil-fuel supply investment two-to-one.', '2026-06-18T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000019', 'f0000000-0000-4000-8000-000000000019', 'https://www.irena.org/-/media/Files/IRENA/Agency/Publication/2024/Sep/IRENA_Renewable_power_generation_costs_in_2023_executive_summary.pdf', 'IRENA — Renewable Power Generation Costs in 2023', 'New onshore wind (USD 0.034/kWh) and solar PV (USD 0.043/kWh) are the cheapest sources of new electricity; 81% of 2023 renewable additions were cheaper than the cheapest fossil option.', 'Not in the source review: IRENA’s cost report is real and authoritative but was not part of the source review, so this factor is held at "pending" and kept off the verified field and the Clock aggregate until it is reviewed.', '2026-06-19T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000020', 'f0000000-0000-4000-8000-000000000020', 'https://report-2023.global-tipping-points.org/', 'Global Tipping Points Report 2023 (University of Exeter, Global Systems Institute)', 'Positive tipping points have already been crossed in the adoption of solar PV and wind power globally, with solar PV capacity doubling every 2–3 years.', 'Not in the source review: the Global Tipping Points Report is real and well-cited but was not part of the source review, so this factor is held at "pending" and kept off the verified field and the Clock aggregate until it is reviewed.', '2026-06-20T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000021', 'f0000000-0000-4000-8000-000000000021', 'https://www.rescoop.eu/uploads/rescoop/downloads/REScoop-Annual-Report-2023_digital.pdf', 'REScoop.eu — European federation of citizen energy cooperatives', 'REScoop.eu represents over 2,250 energy cooperatives and 1,500,000 European citizens.', 'Not in the source review: REScoop.eu’s report is real but was not part of the source review, so this factor is held at "pending" and kept off the verified field and the Clock aggregate until it is reviewed. Pin placed in Germany, which hosts the largest number of energy cooperatives; the movement is pan-European.', '2026-06-21T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000022', 'f0000000-0000-4000-8000-000000000022', 'https://www.globalforestwatch.org/about/', 'Global Forest Watch (World Resources Institute)', 'All data, maps, and analysis tools on GFW are free and open access, providing near-real-time information on forest change.', 'Not in the source review: Global Forest Watch is a real, well-known platform but was not part of the source review, so this factor is held at "pending" and kept off the verified field and the Clock aggregate until it is reviewed.', '2026-06-22T12:00:00.000Z'::timestamptz),
  ('c0000000-0000-4000-8000-000000000023', 'f0000000-0000-4000-8000-000000000023', 'https://www.sec.gov/files/staff-report-equity-options-market-struction-conditions-early-2021.pdf', 'U.S. Securities and Exchange Commission (Staff Report, 2021)', 'GameStop’s share price rose from a January 4 close of $17.25 to over $500 in pre-market trading on January 28, 2021, driven by retail investors coordinating on social media.', 'Source re-pointed to the SEC staff report (the bibliography entry) for the price move; Melvin Capital’s ~53% / $6.8B January loss (CNBC) and the $2.75B Citadel/Point72 injection (Bloomberg) are the corroborating figures. Cited as an example of rapid decentralised coordination, not an investment endorsement; brokerage trading restrictions (e.g. Robinhood) followed.', '2026-06-23T12:00:00.000Z'::timestamptz)
